// Official municipal visitor information reviewed 2026-11-06. These are not property-level claims.
export const shorelineGuides: Record<string,{en:string;es:string;source:string;places:string[]}>={
  easthaven:{
    en:"East Haven offers shoreline recreation at East Haven Town Beach on Cosey Beach Avenue, where the town lists a beach, playground, splash pad, picnic area and pavilion; the recreation department also lists bocce and volleyball courts. Check current beach parking, seasonal access and water-quality notices before visiting. Farm River State Park, at 150 Short Beach Road, protects tidal wetlands and woodland along the estuary. Its self-guided nature trail is about one mile, with steep overlooks in places; limited parking is available at the Short Beach Road entrance. The marina entrance off Mansfield Grove Road is gated and requires an appropriate boating or dock-access pass. Low tides can make launching or returning kayaks difficult. Other town recreation facilities include the Hudson Street Athletic Complex and East Haven Town Green. For a move, confirm a specific property's assessment and taxes with the town, school enrollment with the district, and electricity, water, gas and internet service with each provider; availability and school assignments should never be inferred from nearby addresses.",
    es:"East Haven ofrece recreación costera en East Haven Town Beach, en Cosey Beach Avenue. El municipio enumera playa, parque infantil, zona de juegos de agua, área de pícnic y pabellón; el departamento de recreación también indica canchas de bochas y voleibol. Antes de ir, consulta los avisos vigentes sobre estacionamiento, acceso de temporada y calidad del agua. Farm River State Park, en 150 Short Beach Road, protege humedales de marea y bosques junto al estuario. Su sendero autoguiado de naturaleza tiene aproximadamente una milla y algunos miradores terminan en pendientes pronunciadas; el estacionamiento en la entrada de Short Beach Road es limitado. El acceso al puerto deportivo desde Mansfield Grove Road tiene una barrera y requiere el pase correspondiente para embarcaciones o muelles. La marea baja puede dificultar la salida y el regreso en kayak. Otras instalaciones recreativas municipales incluyen Hudson Street Athletic Complex y East Haven Town Green. Si estás considerando mudarte, confirma la tasación y los impuestos de la propiedad con el municipio, la inscripción escolar con el distrito y la disponibilidad de electricidad, agua, gas e internet con cada proveedor; no supongas que una dirección tiene los mismos servicios o escuelas que otra cercana.",
    source:"https://ctparks.com/parks/farm-river-state-park",
    places:["East Haven Town Beach","Farm River State Park","Hudson Street Athletic Complex","East Haven Town Green"]
  },
  darien:{
    en:"Darien's public parks range from shoreline recreation to neighborhood green spaces. Weed Beach on Nearwater Lane has a swimming area, playgrounds, tennis and paddle courts and picnic facilities. Pear Tree Point Beach, near the mouth of the Goodwives River, has beaches and a boat launch, but the town has posted construction-related closure notices for improvement work; confirm reopening before planning a visit. Away from the water, Cherry Lawn Park offers courts, a playground and a community garden, while Tilley Pond Park provides a smaller downtown green space. Seasonal beach access requires the appropriate emblem or day pass, and swimming can be suspended after heavy rainfall or poor water-quality results. Check current town notices, fees and facility status. For a move, verify assessments, taxes, school enrollment and utility availability for the individual address through town departments and providers.",
    es:"Los parques públicos de Darien van desde espacios costeros hasta zonas verdes de barrio. Weed Beach, en Nearwater Lane, cuenta con zona de baño, juegos infantiles, canchas de tenis y pádel y espacios para pícnic. Pear Tree Point Beach, cerca de la desembocadura del río Goodwives, tiene playas y una rampa para embarcaciones, pero el municipio ha publicado avisos de cierre por obras de mejora; confirma su reapertura antes de visitarla. Lejos de la costa, Cherry Lawn Park ofrece canchas, juegos infantiles y un huerto comunitario, mientras que Tilley Pond Park es un espacio verde más pequeño cerca del centro. Durante la temporada, el acceso a las playas requiere el distintivo o pase diario correspondiente, y la natación puede suspenderse después de lluvias intensas o por resultados de calidad del agua. Consulta los avisos, tarifas y condiciones actuales del municipio. Si piensas mudarte, verifica tasaciones, impuestos, inscripción escolar y servicios disponibles para cada dirección con las oficinas y proveedores correspondientes.",
    source:"https://darienct.gov/234/Parks-Beaches",
    places:["Weed Beach","Pear Tree Point Beach Park","Cherry Lawn Park","Tilley Pond Park","Stony Brook Park"]
  },
  meriden:{
    en:"Meriden's Hubbard Park brings together Mirror Lake, walking paths, playgrounds, picnic areas and the James J. Barry Bandshell. Trails climb through the Hanging Hills toward Castle Craig, a stone observation tower dedicated in 1900. The city describes a seasonal access road to the tower, generally May 10 through October 30, weather permitting; check current road and trail notices before visiting, particularly outside that window. Meriden Green, near East Main and Pratt Streets, is another municipal gathering space with an amphitheater. The city Parks and Recreation office manages programs and facility requests; confirm permit, pool-pass and reservation rules directly rather than relying on old posted schedules. If considering a move, verify property assessment, taxes, school assignment and available utilities for the specific address through the appropriate municipal offices and providers.",
    es:"Hubbard Park, en Meriden, reúne Mirror Lake, senderos, áreas de juegos, espacios para pícnic y el escenario James J. Barry Bandshell. Los caminos suben por las Hanging Hills hacia Castle Craig, una torre de observación de piedra inaugurada en 1900. Según el municipio, la carretera de acceso a la torre funciona por temporada, generalmente del 10 de mayo al 30 de octubre, si el tiempo lo permite; consulta los avisos actuales sobre caminos y senderos antes de ir, especialmente fuera de esas fechas. Meriden Green, cerca de East Main Street y Pratt Street, es otro espacio público con anfiteatro. La oficina municipal de Parques y Recreación administra actividades y solicitudes de instalaciones; confirma directamente los permisos, pases de piscina y reservas en lugar de confiar en horarios antiguos. Si piensas mudarte, verifica la tasación, los impuestos, la asignación escolar y los servicios disponibles para la dirección específica con las oficinas y empresas correspondientes.",
    source:"https://www.meridenct.gov/city-services/parks-and-recreation/hubbard-park/",
    places:["Hubbard Park","Castle Craig","Mirror Lake","James J. Barry Bandshell","Meriden Green"]
  },
  "east-haven":{
    en:"East Haven's shoreline offers two different kinds of outdoor outings. The town beach on Cosey Beach Avenue has a beach pavilion, splash pad, bocce and volleyball courts; consult East Haven Recreation for current beach parking, seasonal swimming notices and facility schedules. Farm River State Park at 150 Short Beach Road offers an easy self-guided nature trail through coastal habitat, with birdwatching around the tidal marsh and river estuary. Parking at the state park's main entrance is limited, and marina access requires the appropriate pass or permit; do not assume the gated launch is open to every visitor. For a move, use East Haven Town Hall's municipal departments to check land records, assessments and taxes, and confirm schools and utility service for the specific property.",
    es:"La costa de East Haven ofrece dos experiencias al aire libre diferentes. La playa municipal en Cosey Beach Avenue cuenta con pabellón, zona de juegos de agua y canchas de bochas y voleibol; consulta al Departamento de Recreación para conocer las normas actuales de estacionamiento, avisos de baño y horarios. Farm River State Park, en 150 Short Beach Road, ofrece un sendero autoguiado sencillo por un entorno costero y oportunidades para observar aves en las marismas y el estuario. El estacionamiento de la entrada principal es limitado y el acceso a la marina requiere el pase o permiso correspondiente; no supongas que la rampa con portón está abierta a todos. Si piensas mudarte, consulta las oficinas del ayuntamiento para registros de propiedad, tasaciones e impuestos y confirma escuelas y servicios públicos para la vivienda concreta.",
    source:"https://ctparks.com/parks/farm-river-state-park",
    places:["East Haven Town Beach","Farm River State Park"]
  },

  "north-haven":{
    en:"North Haven's municipal reports identify Peter's Rock, Hansen Farm Park and Spring Road among the town's important open spaces. The Parks Division maintains athletic fields, courts, playgrounds and natural recreation areas; individual facilities may have changing rules or seasonal access. The town also describes community recreation programs, concerts on the Green and activities at the Walter J. Gawrych Community Pool. Check the current Recreation Department calendar and pool admission rules before visiting. Wharton Brook State Park, on the North Haven–Wallingford boundary, also offers pondside recreation; check Connecticut State Parks' Wharton Brook page for current swimming, fishing and parking rules. For a move, consult the town assessor and Town Clerk for property records, and verify taxes, schools and utility service for the specific address rather than assuming townwide uniformity.",
    es:"Los informes municipales de North Haven identifican Peter's Rock, Hansen Farm Park y Spring Road entre los espacios abiertos importantes del municipio. La división de parques mantiene campos deportivos, canchas, parques infantiles y áreas naturales; las normas y el acceso estacional pueden variar. El municipio también describe programas recreativos comunitarios, conciertos en el Green y actividades en la piscina Walter J. Gawrych. Consulta el calendario actual del Departamento de Recreación y las reglas de entrada a la piscina antes de ir. Wharton Brook State Park, en el límite de North Haven y Wallingford, también ofrece actividades junto al estanque; consulta la página estatal del parque para conocer las normas vigentes de natación, pesca y estacionamiento. Si piensas mudarte, consulta al tasador y al secretario municipal sobre los registros de propiedad y verifica impuestos, escuelas y servicios públicos para la dirección concreta.",
    source:"https://www.town.north-haven.ct.us/Document%20Center/Community/North%20Haven%20Calendar%202023-24.pdf",
    places:["Peter's Rock","Hansen Farm Park","Spring Road Open Space","North Haven Green","Walter J. Gawrych Community Pool","Wharton Brook State Park"]
  },
  wolcott:{
    en:"Wolcott's municipal recreation directory identifies Peterson Park at 123 Mad River Road, with playgrounds, trails, courts and picnic pavilions, and the 3.5-mile Mill Pond Way walking route around Scovill Reservoir. Woodtick Reservoir has designated shoreline access and a public boat launch; the town restricts motors to electric power and prohibits sailboats. Other options include Farmingbury Hills Golf Course and the Woodtick Recreation Area pavilion at 201 Nichols Road. The town's Woodtick swimming page still displays a 2025 closure notice, so do not assume the beach is open: confirm current swimming status, reservations and access rules directly with Wolcott. People moving to town can consult the municipal assessor, town clerk, tax collector and sewer/water departments for address-specific records and services.",
    es:"El directorio recreativo municipal de Wolcott incluye Peterson Park, en 123 Mad River Road, con áreas de juegos, senderos, canchas y pabellones para pícnic, y el recorrido peatonal Mill Pond Way de 3,5 millas alrededor del embalse Scovill. Woodtick Reservoir dispone de puntos de acceso desde la orilla y una rampa pública para embarcaciones; el municipio solo permite motores eléctricos y prohíbe los veleros. Otras opciones son Farmingbury Hills Golf Course y el pabellón del área recreativa Woodtick, en 201 Nichols Road. La página municipal de natación de Woodtick todavía muestra un aviso de cierre de 2025; no des por hecho que la playa esté abierta y confirma con Wolcott el estado actual, las reservas y las normas de acceso. Quienes se muden pueden consultar las oficinas municipales del tasador, secretario, recaudador y servicios de agua y alcantarillado para obtener información específica de cada dirección.",
    source:"https://www.wolcottct.org/262/Recreation-Leisure",
    places:["Peterson Park","Mill Pond Way Walking Trail","Woodtick Reservoir","Farmingbury Hills Golf Course","Woodtick Recreation Area"]
  },
  waterbury:{
    en:"Waterbury maintains a network of neighborhood parks, recreation centers and public sports facilities. Fulton Park on Cooke Street is known for its landscaped ponds and walking paths, while Hamilton Park on Hamilton Park Road and Lakewood Park on Lakewood Road offer additional places to spend time outdoors. The city also operates East Mountain and Western Hills municipal golf courses. Recreation programs serve children, adults and older residents through several centers; ask the Bureau of Recreation about current registration and eligibility. Lakewood swimming access and city pools are seasonal and can close for water-quality or maintenance reasons, so verify the latest city notices before making plans.",
    es:"Waterbury mantiene una red de parques vecinales, centros recreativos e instalaciones deportivas públicas. Fulton Park, en Cooke Street, es conocido por sus estanques ajardinados y senderos; Hamilton Park, en Hamilton Park Road, y Lakewood Park, en Lakewood Road, ofrecen otros espacios al aire libre. La ciudad también administra los campos de golf municipales East Mountain y Western Hills. Los programas recreativos para niños, adultos y personas mayores se ofrecen en varios centros; consulta con la oficina municipal de Recreación sobre inscripciones y requisitos actuales. El acceso para nadar en Lakewood y las piscinas municipales es estacional y puede suspenderse por la calidad del agua o por mantenimiento; revisa los avisos oficiales antes de ir.",
    source:"https://www.waterburyct.org/services/public-works/recreation",
    places:["Fulton Park","Hamilton Park","Lakewood Park","East Mountain Golf Course","Western Hills Golf Course"]
  },
  orange:{
    en:"Orange offers both community recreation and quieter protected landscapes. High Plains Community Center at 525 Orange Center Road has the Paul Ode Nature Trail, disc golf, an indoor pool and athletic facilities; check the town Parks & Recreation office for program registration, fees and access. For a woodland walk, Turkey Hill Preserve has a marked blue loop trail off Derby-Milford Road, with wetlands and sensitive habitats that visitors should protect by staying on marked paths. The town also lists Fred Wolfe Park and Old Tavern Road Park among its recreation facilities. Confirm parking, permitted uses and seasonal conditions before visiting.",
    es:"Orange combina instalaciones recreativas comunitarias con espacios naturales protegidos. High Plains Community Center, en 525 Orange Center Road, cuenta con Paul Ode Nature Trail, disc golf, piscina cubierta e instalaciones deportivas; consulta la oficina municipal de Parques y Recreación para conocer inscripciones, tarifas y acceso. Para caminar por el bosque, Turkey Hill Preserve tiene un circuito señalizado en azul con acceso desde Derby-Milford Road, además de humedales y hábitats sensibles que deben protegerse permaneciendo en los senderos marcados. El municipio también incluye Fred Wolfe Park y Old Tavern Road Park entre sus instalaciones recreativas. Confirma las normas de estacionamiento, los usos permitidos y las condiciones de temporada antes de visitar.",
    source:"https://www.orange-ct.gov/Facilities",
    places:["High Plains Community Center","Paul Ode Nature Trail","Turkey Hill Preserve","Fred Wolfe Park","Old Tavern Road Park"]
  },
  naugatuck:{
    en:"The Larkin State Park Trail reaches its eastern end in Naugatuck near Route 63, where Connecticut State Parks identifies a small parking area at Whittemore Glen State Park. The former railroad corridor offers walking, cycling and horseback riding over surfaces that vary from packed earth to gravel and older rail ballast. A separate stretch between Kettletown Road in Southbury and Christian Street in Oxford remains closed following the August 2024 floods; consult the official trail map and closure alert before planning a longer trip. Keep dogs leashed and check conditions after wet weather.",
    es:"El sendero estatal Larkin llega a su extremo oriental en Naugatuck, cerca de la Ruta 63, donde Connecticut State Parks señala un pequeño estacionamiento en Whittemore Glen State Park. Este antiguo corredor ferroviario permite caminar, andar en bicicleta y montar a caballo sobre superficies que varían entre tierra compactada, grava y balasto ferroviario. Un tramo separado entre Kettletown Road en Southbury y Christian Street en Oxford sigue cerrado tras las inundaciones de agosto de 2024; consulta el mapa oficial y el aviso de cierre antes de planificar un recorrido largo. Lleva a los perros con correa y revisa las condiciones después de la lluvia.",
    source:"https://ctparks.com/parks/larkin-state-park-trail",
    places:["Larkin State Park Trail","Whittemore Glen State Park"]
  },
  clinton:{
    en:"Clinton Town Beach on Waterside Lane offers picnic areas, a playground, walking paths and seasonal beach access. The town's facilities directory also lists Bailey's Dog Park and Ethel Peters Recreation Complex. For a harbor outing, Clinton Town Marina has a kayak launch and boat ramp, with applicable fees and seasonal arrangements. Check town notices for beach passes, parking, boat-launch access and facility hours before visiting.",
    es:"Clinton Town Beach, en Waterside Lane, ofrece áreas para pícnic, parque infantil, senderos y acceso estacional a la playa. El directorio municipal también incluye Bailey's Dog Park y Ethel Peters Recreation Complex. Para visitar el puerto, Clinton Town Marina cuenta con acceso para kayaks y rampa para embarcaciones, sujetos a tarifas y condiciones de temporada. Consulta los avisos municipales sobre pases de playa, estacionamiento, acceso a la rampa y horarios antes de ir.",
    source:"https://clintonct.org/Facilities",
    places:["Clinton Town Beach","Bailey's Dog Park","Ethel Peters Recreation Complex","Clinton Town Marina"]
  },
  killingworth:{
    en:"Killingworth is home to Chatfield Hollow State Park, where Connecticut DEEP identifies hiking, picnicking, fishing and seasonal swimming among recreational options. The park has woodland trails and a scenic covered bridge; trail difficulty varies. Before setting out, review DEEP's current park notices, trail maps, swimming conditions and any parking or access restrictions. Nearby Cockaponset State Forest offers additional regional outdoor exploration, but check the exact trailhead and municipality before traveling.",
    es:"Killingworth alberga Chatfield Hollow State Park, donde el Departamento de Energía y Protección Ambiental de Connecticut identifica senderismo, pícnics, pesca y natación de temporada entre las actividades. El parque tiene senderos boscosos y un puente cubierto pintoresco; la dificultad de los senderos varía. Antes de salir, revisa los avisos actuales del estado, los mapas, las condiciones para nadar y las restricciones de acceso o estacionamiento. Cockaponset State Forest ofrece otras opciones en la región; confirma la ubicación exacta del inicio del sendero y el municipio antes de viajar.",
    source:"https://portal.ct.gov/deep/state-parks/skys-the-limit",
    places:["Chatfield Hollow State Park","Cockaponset State Forest"]
  },
  guilford:{
    en:"Guilford offers several distinct outdoor outings. Jacobs Beach has a swimming beach and recreation facilities, while Chaffinch Island Park is a waterfront picnic and fishing destination rather than a swimming beach. Nut Plains Park includes trails and a dog park. For a longer woodland hike, the Guilford Land Conservation Trust maintains the Westwoods trail network, which includes rocky terrain and wetland crossings. Check town beach-pass requirements, trail maps, parking rules and current conditions before setting out.",
    es:"Guilford ofrece distintas opciones para disfrutar al aire libre. Jacobs Beach cuenta con playa para nadar e instalaciones recreativas, mientras que Chaffinch Island Park es un lugar costero para hacer pícnics y pescar, no para nadar. Nut Plains Park tiene senderos y un parque para perros. Para una caminata más larga por el bosque, Guilford Land Conservation Trust mantiene la red de senderos Westwoods, con terreno rocoso y pasos por humedales. Consulta los requisitos de pases de playa, los mapas, las normas de estacionamiento y las condiciones actuales antes de salir.",
    source:"https://visitguilfordct.com/beaches-parks/",
    places:["Jacobs Beach","Chaffinch Island Park","Nut Plains Park","Westwoods"]
  },
  madison:{
    en:"Madison's municipal recreation directory identifies Surf Club, East Wharf and West Wharf as town beaches, alongside Hammonasset Beach State Park. For inland outings, Salt Meadow Park offers a former-airfield walking path and coastal-forest trails, while Bauer Park and Rockland Preserve provide additional walking opportunities. At Hammonasset Beach State Park, the state lists a two-mile beach, the Meigs Point Nature Center, a three-mile multi-use bicycle trail, the 1.4-mile Meigs Point shoreline trail and the 1.1-mile Willard's Island marsh loop. The campground requires reservations; the state lists its 2027 season as May 28 through October 11, subject to change. The park entrance is at 1288 Boston Post Road; state-listed day-use hours are 8 a.m. to sunset. The state's 2026 campground season ended October 12, so confirm new-season dates before planning an overnight stay. Town beach parking rules and seasonal fees differ from state-park arrangements; check official access notices, posted restrictions and conditions before visiting.",
    es:"El directorio municipal de recreación de Madison identifica Surf Club, East Wharf y West Wharf como playas municipales, además del parque estatal Hammonasset Beach. Para paseos tierra adentro, Salt Meadow Park ofrece un sendero sobre la antigua pista de un aeródromo y caminos por el bosque costero; Bauer Park y Rockland Preserve brindan otras opciones para caminar. En Hammonasset Beach State Park, el estado indica una playa de dos millas, el centro de naturaleza Meigs Point, un sendero multiuso de tres millas para bicicletas, el sendero costero Meigs Point de 1,4 millas y el circuito de marismas Willard's Island de 1,1 millas. El campamento requiere reservas; el estado indica que la temporada de 2027 será del 28 de mayo al 11 de octubre, sujeta a cambios. La entrada está en 1288 Boston Post Road; el horario diurno publicado por el estado es de 8 a. m. hasta la puesta del sol. La temporada de campamento de 2026 terminó el 12 de octubre; confirma las fechas de la próxima temporada antes de planear una estancia nocturna. Las normas de estacionamiento y tarifas de temporada de las playas municipales difieren de las del parque estatal; consulta los avisos oficiales, las restricciones y las condiciones antes de visitar.",
    source:"https://ctparks.com/parks/hammonasset-beach-state-park",
    places:["Surf Club Park","East Wharf Beach","West Wharf Beach","Salt Meadow Park","Bauer Park","Rockland Preserve","Hammonasset Beach State Park"]
  },
  milford:{
    en:"Milford's official Open Space Walks guide maps seven walking areas: Beaver Brook, Eisenhower Park, Great River Walk, Mondo Ponds, Silver Sands State Park, Solomon Woods and Wilcox Park. Eisenhower Park has woodland and riverside trails, with its main entrance at 701 North Street. Wilcox Park's harbor-view trails can be reached from Shipyard Lane behind the Milford Public Library; boat-launch parking requires a pass. The city's tourism directory also lists Walnut, Anchor and Gulf beaches, the Connecticut Audubon Coastal Center and the Milford Arts Council. At Silver Sands, the sandbar toward Charles Island is hazardous when tides rise; Connecticut State Parks prohibits crossing to the island from May 1 through September 9 to protect nesting birds. Bicycles are not permitted on the Silver Sands boardwalk, and the state posts seasonal swimming-water monitoring results. Beach rules, parking, water advisories and recreation schedules can change, so check the relevant city or state office before visiting. For a move, use Milford's municipal department directory to contact the assessor, tax collector and public works, and verify school assignment, taxes and utilities for the particular address.",
    es:"La guía oficial de paseos naturales de Milford incluye siete áreas: Beaver Brook, Eisenhower Park, Great River Walk, Mondo Ponds, Silver Sands State Park, Solomon Woods y Wilcox Park. Eisenhower Park tiene senderos boscosos y junto al río; su entrada principal está en 701 North Street. Se puede llegar a los senderos con vistas al puerto de Wilcox Park por Shipyard Lane, detrás de la biblioteca pública de Milford; el estacionamiento para la rampa de embarcaciones requiere un permiso. El directorio turístico municipal también incluye las playas Walnut, Anchor y Gulf, el Connecticut Audubon Coastal Center y el Milford Arts Council. En Silver Sands, el banco de arena hacia Charles Island es peligroso cuando sube la marea; los parques estatales prohíben cruzar a la isla del 1 de mayo al 9 de septiembre para proteger a las aves que anidan. No se permiten bicicletas en el paseo marítimo de Silver Sands, y el estado publica resultados de vigilancia estacional de la calidad del agua para nadar. Las reglas de playa, estacionamiento, avisos sobre el agua y horarios recreativos pueden cambiar; consulta a la ciudad o al estado antes de ir. Si piensas mudarte, usa el directorio municipal para contactar al tasador, recaudador de impuestos y obras públicas, y confirma la escuela asignada, los impuestos y los servicios para la dirección específica.",
    source:"https://www.milfordct.us/490/Milford-Open-Space-Walks",
    places:["Eisenhower Park","Wilcox Park","Mondo Ponds","Walnut Beach","Silver Sands State Park","Connecticut Audubon Coastal Center"]
  },
  branford:{
    en:"Branford's town-maintained walking-trails page links to trail maps for local outdoor exploration. The town's nature guide identifies Supply Pond, Pisgah Brook, Beacon Hill, Stony Creek Quarry and the Stony Creek Trolley Trail as accessible natural areas. Choose a route using the official maps, check trail conditions and parking rules, and respect protected habitats and posted restrictions.",
    es:"La página municipal de senderos de Branford ofrece enlaces a mapas para explorar al aire libre. La guía de naturaleza del municipio identifica Supply Pond, Pisgah Brook, Beacon Hill, Stony Creek Quarry y Stony Creek Trolley Trail como espacios naturales accesibles. Elige una ruta con los mapas oficiales, comprueba el estado de los senderos y las normas de estacionamiento, y respeta los hábitats protegidos y las restricciones señalizadas.",
    source:"https://www.branford-ct.gov/357/Walking-Trails",
    places:["Supply Pond Preserve","Pisgah Brook Preserve","Beacon Hill","Stony Creek Trolley Trail"]
  },
  hamden:{
    en:"Hamden offers several distinct outdoor outings. Sleeping Giant State Park at 200 Mount Carmel Avenue has a three-mile gravel out-and-back Tower Trail to a stone observation tower, a 1.5-mile moderate Nature Trail loop and a more strenuous blue-blazed Quinnipiac Trail climb. The state lists daily access from 8 a.m. to sunset. The gray-blazed Tower Trail is the easier tower approach; the blue-blazed Quinnipiac route is strenuous and includes steep rock. The park can fill to capacity, so visitors should confirm current trail maps, parking rules and capacity notices before setting out. Brooksvale Park, operated by the town, combines walking trails with a working-farm atmosphere, gardens and a barnyard; visitors must not feed the animals. West Rock Ridge State Park also extends into Hamden, with ridge hiking and views across the New Haven area. Check each park's official rules and seasonal access before visiting.",
    es:"Hamden ofrece varias opciones para disfrutar al aire libre. Sleeping Giant State Park, en 200 Mount Carmel Avenue, cuenta con Tower Trail, un recorrido de ida y vuelta de tres millas por grava hasta una torre de observación de piedra; Nature Trail, un circuito moderado de 1,5 millas; y una subida más exigente por el sendero Quinnipiac, marcado en azul. El estado indica un horario diario de 8 a. m. hasta la puesta del sol. Tower Trail, marcado en gris, es la ruta más sencilla hacia la torre; el sendero Quinnipiac, marcado en azul, es exigente y tiene tramos de roca empinados. El parque puede alcanzar su aforo máximo, así que conviene confirmar los mapas, las normas de estacionamiento y los avisos de aforo antes de salir. Brooksvale Park, administrado por el municipio, combina senderos con un ambiente de granja, jardines y animales de corral; está prohibido alimentarlos. West Rock Ridge State Park también se extiende por Hamden y ofrece caminatas por la cresta y vistas de la zona de New Haven. Consulta las normas oficiales y el acceso de temporada de cada parque antes de ir.",
    source:"https://ctparks.com/parks/sleeping-giant-state-park",
    places:["Sleeping Giant State Park","Brooksvale Park","West Rock Ridge State Park"]
  },
  woodbridge:{
    en:"Woodbridge's official trail-map directory includes Alice Newton Street Memorial Park, the Fitzgerald Tract, Racebrook Tract and several other walking areas. Alice Newton Street Memorial Park is intended for daylight hiking and nature study; dogs must be leashed, and motorized vehicles and horses are prohibited. The town also identifies three Regional Water Authority trail systems that require a separate RWA recreation permit. Review the linked maps and current access rules before visiting.",
    es:"El directorio oficial de senderos de Woodbridge incluye Alice Newton Street Memorial Park, Fitzgerald Tract, Racebrook Tract y otras áreas para caminar. Alice Newton Street Memorial Park está destinado a caminatas y observación de la naturaleza durante el día; los perros deben llevar correa y se prohíben los vehículos motorizados y los caballos. El municipio también identifica tres sistemas de senderos de la Regional Water Authority que requieren un permiso recreativo independiente. Consulta los mapas y las normas de acceso vigentes antes de visitar.",
    source:"https://www.woodbridgect.org/209/Trail-Maps",
    places:["Alice Newton Street Memorial Park","Fitzgerald Tract","Racebrook Tract"]
  },
  wallingford:{
    en:"Wallingford offers both town parks and a state park. Community Lake Park at 291 Hall Avenue has a pavilion and access to the Quinnipiac River Linear Trail; Doolittle Park at 78 South Elm Street is another municipal recreation destination. The town also lists Lufbery Park, Pragemann Park and Marcus Cooke Park, along with playgrounds, fields and a disc-golf course. Municipal parks are generally open from sunrise to sunset. Wharton Brook State Park, on the Wallingford–North Haven line at 675 US-5, offers a pondside walking loop, fishing, picnicking and a seasonal swimming area. Connecticut State Parks identifies it as a trout park; consult current water-quality reports, swimming notices and fishing rules rather than assuming water is safe or supervised. For a move, research each property's assessment and tax bill with the Assessor and Tax Collection offices, confirm enrollment with the public schools, and ask the town's Electric, Water and Sewer divisions and other providers about address-specific service. Check park permits and reservations with Parks and Recreation.",
    es:"Wallingford ofrece parques municipales y un parque estatal. Community Lake Park, en 291 Hall Avenue, tiene un pabellón y acceso al sendero lineal del río Quinnipiac; Doolittle Park, en 78 South Elm Street, es otro destino recreativo. El municipio también incluye Lufbery Park, Pragemann Park y Marcus Cooke Park, además de juegos infantiles, campos deportivos y un campo de disc golf. En general, los parques municipales abren del amanecer al atardecer. Wharton Brook State Park, entre Wallingford y North Haven en 675 US-5, ofrece un circuito junto al estanque, pesca, pícnics y una zona de baño de temporada. Connecticut State Parks lo identifica como parque de truchas; consulta los informes actuales de calidad del agua, avisos de baño y normas de pesca sin dar por hecho que el agua es segura o está vigilada. Si piensas mudarte, investiga la tasación y los impuestos de cada propiedad con las oficinas municipales, confirma la inscripción con las escuelas públicas y pregunta a las divisiones de electricidad, agua y alcantarillado y otros proveedores por el servicio en la dirección específica. Consulta permisos y reservas con Parques y Recreación.",
    source:"https://www.wallingfordct.gov/government/departments/parks-recreation/",
    places:["Community Lake Park","Doolittle Park","Lufbery Park","Pragemann Park","Marcus Cooke Park","Wharton Brook State Park"]
  },
  cheshire:{
    en:"Cheshire's municipal recreation areas include Bartlem Park, Cheshire Park and Mixville Recreation Area. The town's published financial report describes sports fields and a playground at Bartlem Park, trails and courts at Cheshire Park, and a pond, picnic areas and walking trails at Mixville. The Farmington Canal Linear Trail also runs through Cheshire and provides a paved route for walking and cycling. Check the town's current recreation notices for pool access, swimming schedules, permits, reservations and facility closures before visiting.",
    es:"Entre los espacios recreativos municipales de Cheshire se encuentran Bartlem Park, Cheshire Park y Mixville Recreation Area. El informe financiero publicado por el municipio describe campos deportivos y un parque infantil en Bartlem Park, senderos y canchas en Cheshire Park, y un estanque, zonas de pícnic y senderos en Mixville. El Farmington Canal Linear Trail también atraviesa Cheshire y ofrece una ruta pavimentada para caminar y andar en bicicleta. Consulta los avisos municipales vigentes sobre acceso a la piscina, horarios de baño, permisos, reservas y cierres antes de visitar.",
    source:"https://www.cheshirect.org/UserFiles/Servers/Server_8580856/File/Government/Finance/2023%20Annual%20Comprehensive%20Financial%20Report.pdf",
    places:["Bartlem Park","Cheshire Park","Mixville Recreation Area","Farmington Canal Linear Trail"]
  },
  derby:{
    en:"Derby connects Naugatuck Valley history with outdoor recreation. Osbornedale State Park, at 43 Chatfield Street, offers trails, fishing and picnicking; the state lists park hours as 8 a.m. to sunset. The adjoining Kellogg Estate at 500 Hawthorne Avenue includes the Kellogg Environmental Center, historic gardens and Osborne Homestead Museum. The state lists museum house tours from June through October, with separate days and hours; verify the current calendar before visiting. Witek Memorial Park offers wooded trails and ponds, while the Derby Greenway follows the Naugatuck and Housatonic river corridors for walking and cycling. Check current park access, trail conditions and facility hours. When comparing homes, confirm parcel-specific assessments and tax bills with Derby officials, school enrollment directly with the district, and water, electricity, gas and internet availability with each provider for the exact address.",
    es:"Derby combina la historia del valle del Naugatuck con actividades al aire libre. Osbornedale State Park, en 43 Chatfield Street, ofrece senderos, pesca y zonas de pícnic; el estado indica que abre de 8 a. m. hasta el atardecer. La finca Kellogg, en 500 Hawthorne Avenue, incluye el Kellogg Environmental Center, jardines históricos y el Osborne Homestead Museum. Según el estado, las visitas a la casa museo se ofrecen de junio a octubre, en días y horarios específicos; consulta el calendario vigente antes de ir. Witek Memorial Park cuenta con senderos boscosos y estanques, mientras que Derby Greenway sigue los corredores de los ríos Naugatuck y Housatonic para caminar y andar en bicicleta. Comprueba los accesos, las condiciones de los senderos y los horarios actuales. Si comparas viviendas, confirma la tasación y los impuestos de cada parcela con Derby, la inscripción escolar directamente con el distrito y la disponibilidad de agua, electricidad, gas e internet con cada proveedor para la dirección exacta.",
    source:"https://ctparks.com/parks/osbornedale-state-park",
    places:["Osbornedale State Park","Osborne Homestead Museum","Kellogg Environmental Center","Witek Memorial Park","Derby Greenway"]
  },
  shelton:{
    en:"Indian Well State Park in Shelton sits beside the Housatonic River and includes a waterfall and gorge, the blue-blazed Paugussett Trail, fishing, a picnic grove and a seasonal swimming beach. The park's official guide notes that vehicle access closes from November through March, although walk-in access remains available. Check current water-quality reports, swimming rules, trail conditions and boat-launch information before visiting; the park prohibits alcohol.",
    es:"Indian Well State Park, en Shelton, está junto al río Housatonic y cuenta con una cascada y un desfiladero, el sendero Paugussett de marcas azules, pesca, una zona de pícnic y una playa de baño estacional. Según la guía oficial, el acceso de vehículos cierra de noviembre a marzo, aunque se permite entrar a pie. Consulta los informes actuales sobre la calidad del agua, las normas de baño, los senderos y el acceso para embarcaciones antes de visitar; está prohibido consumir alcohol.",
    source:"https://ctparks.com/parks/indian-well-state-park",
    places:["Indian Well State Park","Paugussett Trail","Indian Well waterfall"]
  },
  southbury:{
    en:"Southbury's Kettletown State Park overlooks Lake Zoar and offers day-use picnicking and the William Miller Trail. Flood damage from August 2024 has closed the campground and the Pomperaug, Crest and Brook trails; the state says the campground will remain closed through the 2026–2027 seasons. Swimming is prohibited. The Larkin State Park Trail also reaches Southbury, but its section between Kettletown Road and Christian Street in Oxford remains closed. Consult current state maps and alerts before visiting.",
    es:"Kettletown State Park, en Southbury, tiene vistas al lago Zoar y ofrece áreas de pícnic y acceso diurno al sendero William Miller. Las inundaciones de agosto de 2024 causaron el cierre del campamento y de los senderos Pomperaug, Crest y Brook; según el estado, el campamento permanecerá cerrado durante las temporadas 2026–2027. Está prohibido nadar. El sendero estatal Larkin también llega a Southbury, pero sigue cerrado el tramo entre Kettletown Road y Christian Street en Oxford. Consulta los mapas y avisos estatales actuales antes de ir.",
    source:"https://ctparks.com/parks/kettletown-state-park",
    places:["Kettletown State Park","William Miller Trail","Larkin State Park Trail"]
  },
  oxford:{
    en:"The Larkin State Park Trail crosses Oxford on a former railroad corridor shared by walkers, cyclists and horseback riders. Its surfaces vary from packed earth to gravel and can be wet. Connecticut State Parks warns that the section from Kettletown Road in Southbury to Christian Street in Oxford remains closed after the August 2024 floods. Review the official closure map and use only open access points; do not assume the entire route is passable.",
    es:"El sendero estatal Larkin atraviesa Oxford por una antigua vía férrea utilizada por caminantes, ciclistas y jinetes. El terreno alterna tierra compactada y grava, y puede estar húmedo. Connecticut State Parks advierte que el tramo entre Kettletown Road en Southbury y Christian Street en Oxford sigue cerrado por los daños de las inundaciones de agosto de 2024. Revisa el mapa oficial de cierres y utiliza solo los accesos abiertos; no supongas que toda la ruta es transitable.",
    source:"https://ctparks.com/parks/larkin-state-park-trail",
    places:["Larkin State Park Trail"]
  },
  middlebury:{
    en:"The Larkin State Park Trail passes through Middlebury as part of a 10.3-mile former railroad route spanning Southbury, Oxford, Middlebury and Naugatuck. It is used for walking, running, cycling and horseback riding, with varying trail surfaces and seasonal wet spots. A substantial section farther west, from Kettletown Road in Southbury to Christian Street in Oxford, remains closed following 2024 flood damage. Check the state's current trail map and alerts before planning a through-trip.",
    es:"El sendero estatal Larkin pasa por Middlebury y forma parte de una antigua ruta ferroviaria de 10,3 millas que atraviesa Southbury, Oxford, Middlebury y Naugatuck. Se utiliza para caminar, correr, andar en bicicleta y montar a caballo, con superficies variadas y sectores húmedos según la estación. Un tramo importante más al oeste, entre Kettletown Road en Southbury y Christian Street en Oxford, permanece cerrado tras las inundaciones de 2024. Consulta el mapa y los avisos estatales antes de planear un recorrido completo.",
    source:"https://ctparks.com/parks/larkin-state-park-trail",
    places:["Larkin State Park Trail"]
  },
  ansonia:{
    en:"Ansonia residents can explore the nearby Osbornedale State Park landscape along the Derby–Ansonia area, with woodland walks and opportunities to learn about local conservation history. The park's Osborne Homestead Museum and Kellogg Environmental Center are in Derby, so check their separate schedules before traveling. Use Connecticut State Parks' official map to identify the appropriate entrance, trail routes and current restrictions; do not assume that every trailhead or facility is within Ansonia.",
    es:"Quienes viven en Ansonia pueden explorar el paisaje cercano de Osbornedale State Park, en la zona de Derby y Ansonia, con caminatas por el bosque y oportunidades para conocer la historia de la conservación local. Osborne Homestead Museum y Kellogg Environmental Center están en Derby, así que consulta sus horarios por separado antes de viajar. Utiliza el mapa oficial de Connecticut State Parks para identificar la entrada adecuada, los senderos y las restricciones vigentes; no supongas que todos los accesos o instalaciones se encuentran en Ansonia.",
    source:"https://ctparks.com/parks/osbornedale-state-park",
    places:["Osbornedale State Park"]
  },
  beaconfalls:{
    en:"Naugatuck State Forest's East and West Blocks offer outdoor routes around Beacon Falls and neighboring Naugatuck and Oxford. Connecticut DEEP lists an East Block entrance from Andrasko Road in Beacon Falls and a West Block access point at the end of Cold Spring Road; the latter parking area is closed in winter. Trail uses vary by block and route, so consult DEEP's maps and posted signs before hiking or mountain biking. The state lists no parking fee for this forest.",
    es:"Los sectores este y oeste de Naugatuck State Forest ofrecen rutas al aire libre alrededor de Beacon Falls y los municipios vecinos de Naugatuck y Oxford. Connecticut DEEP indica una entrada al sector este desde Andrasko Road en Beacon Falls y un acceso al sector oeste al final de Cold Spring Road; este último estacionamiento cierra durante el invierno. Los usos permitidos varían según el sector y el sendero, por lo que conviene consultar los mapas de DEEP y la señalización antes de caminar o andar en bicicleta de montaña. El estado indica que no se cobra estacionamiento en este bosque.",
    source:"https://portal.ct.gov/deep/state-parks/locate-park-forest/other-state-parks-and-forests",
    places:["Naugatuck State Forest East Block","Naugatuck State Forest West Block"]
  },
  seymour:{
    en:"The Quillinan Reservoir Block of Naugatuck State Forest extends through Seymour and Ansonia. Connecticut DEEP lists a parking area on Route 313 in Seymour and identifies hiking, mountain biking, fishing and paddling among activities in this forest block. Check the official trail map and signs for the appropriate routes, water access and seasonal conditions; do not assume every trail permits every activity. The state lists no parking fee.",
    es:"El sector Quillinan Reservoir de Naugatuck State Forest se extiende por Seymour y Ansonia. Connecticut DEEP señala un estacionamiento en la Ruta 313 en Seymour e incluye senderismo, ciclismo de montaña, pesca y actividades de remo entre las opciones del sector. Consulta el mapa oficial y las señales para conocer los senderos adecuados, los accesos al agua y las condiciones de temporada; no todos los senderos permiten todas las actividades. El estado indica que no se cobra estacionamiento.",
    source:"https://portal.ct.gov/deep/state-parks/locate-park-forest/other-state-parks-and-forests",
    places:["Naugatuck State Forest Quillinan Reservoir Block"]
  },
  bethany:{
    en:"Bethany's Veterans Memorial Park at 265 Beacon Road has a lodge and a pavilion that may be reserved through the town. The town's published park rules require dogs to be leashed and prohibit animals on the beach; nonresidents should check sticker requirements before visiting. The town also lists recreational fields and horse rings at the former airport property on Amity Road. For moving and municipal records, the Bethany Town Clerk at 40 Peck Road handles land records and vital records; confirm office hours, appointment requirements and any fees directly with the town. Check current park notices and swimming advisories before a trip.",
    es:"Veterans Memorial Park, en 265 Beacon Road en Bethany, cuenta con un edificio y un pabellón que pueden reservarse por medio del municipio. Las normas publicadas exigen llevar a los perros con correa y prohíben los animales en la playa; las personas no residentes deben consultar los requisitos de identificación o permiso antes de visitar. El municipio también ofrece campos recreativos y pistas para caballos en el antiguo terreno del aeropuerto de Amity Road. Para trámites de mudanza y documentos municipales, la oficina del secretario municipal de Bethany, en 40 Peck Road, administra registros de propiedad y documentos vitales; confirma directamente horarios, citas y tarifas. Consulta los avisos del parque y las alertas sobre el agua antes de ir.",
    source:"https://www.bethany-ct.com/reservation-and-rentals",
    places:["Veterans Memorial Park","Bethany Airport Recreation Fields"]
  },
  prospect:{
    en:"Prospect's recreation facilities directory lists Canfield Park at 36 Coer Road with a multipurpose field and tennis courts, Caplan Park at 91 New Haven Road, and McGrath Park at 21 Cheshire Road with a pond. The department also lists Prospect Green and community-center spaces for local activities. For a move to town, Prospect Town Hall at 36 Center Street provides access to the assessor, tax collector, town clerk and building department; the municipal website links to land records, property cards and tax payments. Check facility reservations and current rules with Parks and Recreation before visiting, and confirm municipal office hours before a trip.",
    es:"El directorio de instalaciones recreativas de Prospect incluye Canfield Park, en 36 Coer Road, con un campo multiuso y canchas de tenis; Caplan Park, en 91 New Haven Road; y McGrath Park, en 21 Cheshire Road, con un estanque. El departamento también incluye Prospect Green y espacios del centro comunitario para actividades locales. Si te mudas al municipio, el ayuntamiento en 36 Center Street reúne servicios del tasador, recaudador de impuestos, secretario municipal y departamento de construcción; el sitio oficial enlaza a registros de propiedad, fichas de inmuebles y pagos de impuestos. Consulta las reservas y las normas vigentes con Parques y Recreación antes de visitar y confirma los horarios de las oficinas municipales.",
    source:"https://prospectct.myrec.com/info/facilities/default.aspx",
    places:["Canfield Park","Caplan Park","McGrath Park","Prospect Green"]
  },
  stamford:{
    en:"Stamford's city parks offer shoreline recreation and inland trails. Cove Island Park at 1125 Cove Road has two sandy beaches, a walking and running loop, playground, picnic areas, sports courts and a wildlife sanctuary noted for birdwatching. Cummings Park on Shippan Avenue has a beach, boardwalk and fishing pier, while Mianus River Park at 100 Merriebrook Lane offers wooded walking trails along the river. Mill River Park near Washington Boulevard and Scalzi Park on Bridge Street are additional city-listed recreation destinations. Check the City of Stamford's current beach parking permits, park-use rules and seasonal notices before visiting. For a prospective move, verify an individual property's assessment, tax bill, school assignment and utility availability with the city, school district and service providers rather than assuming conditions from a neighborhood description.",
    es:"Los parques municipales de Stamford ofrecen actividades junto a la costa y senderos tierra adentro. Cove Island Park, en 1125 Cove Road, tiene dos playas de arena, un circuito para caminar o correr, juegos infantiles, áreas de pícnic, canchas deportivas y un santuario de fauna conocido por la observación de aves. Cummings Park, en Shippan Avenue, cuenta con playa, paseo costero y muelle de pesca; Mianus River Park, en 100 Merriebrook Lane, ofrece senderos arbolados junto al río. Mill River Park, cerca de Washington Boulevard, y Scalzi Park, en Bridge Street, son otros espacios recreativos incluidos en el directorio municipal. Antes de visitar, consulta los permisos vigentes de estacionamiento en las playas, las normas de uso y los avisos de temporada del municipio. Si estás pensando en mudarte, confirma la tasación, los impuestos, la asignación escolar y los servicios disponibles para cada dirección con la ciudad, el distrito escolar y las empresas proveedoras; no los deduzcas de una descripción del vecindario.",
    source:"https://www.stamfordct.gov/around-town/parks/parks-and-recreation-sites",
    places:["Cove Island Park","Cummings Park","Mianus River Park","Mill River Park","Scalzi Park"]
  },
  fairfield:{
    en:"Fairfield's Jennings Beach is a municipal shoreline destination at 880 South Benson Road. Before planning a visit, consult the Town of Fairfield for current beach-pass eligibility, parking arrangements, seasonal swimming guidance and any posted restrictions. People considering a move can use the town's official property and municipal resources to research an individual address; a beach's proximity does not establish property-level access rights or conditions.",
    es:"Jennings Beach es una playa municipal de Fairfield situada en 880 South Benson Road. Antes de visitarla, consulta al municipio de Fairfield sobre los requisitos actuales de pases, estacionamiento, condiciones de baño durante la temporada y restricciones publicadas. Quienes estén pensando en mudarse pueden consultar los recursos municipales y de propiedades para investigar una dirección específica; vivir cerca de la playa no garantiza derechos de acceso ni condiciones particulares de una propiedad.",
    source:"https://fairfieldct.org/Jennings%20Beach%20Park%20RAR%2006-02-2022.pdf",
    places:["Jennings Beach"]
  },

  "new-haven":{
    en:"New Haven's city parks offer contrasting outings. East Rock Park at 41 Cold Spring Street has wooded trails, a summit overlook and the Trowbridge Environmental Center; the city lists more than ten miles of trails and says the park closes at sunset. Edgewood Park along Edgewood Avenue offers walking, ponds, a sensory trail, playgrounds and a skate park; swimming in its ponds and river is prohibited. Edgerton Park at 75 Cliff Street and West River Memorial Park at 200 Derby Avenue are also listed in the municipal parks directory. Lighthouse Point Park at 2 Lighthouse Road has a historic lighthouse and carousel, but the city currently posts a temporary closure due to storm damage: do not plan entry until the Parks Department confirms reopening. Before visiting any park, check current hours, trail closures and permit rules. People exploring a move should verify individual property assessments and taxes with the city, school enrollment with the school district and utility availability with providers; park proximity does not establish property rights.",
    es:"Los parques municipales de New Haven ofrecen distintas experiencias. East Rock Park, en 41 Cold Spring Street, cuenta con senderos arbolados, un mirador en la cima y el centro ambiental Trowbridge; la ciudad indica que hay más de diez millas de senderos y que el parque cierra al atardecer. Edgewood Park, a lo largo de Edgewood Avenue, ofrece paseos, estanques, un sendero sensorial, juegos infantiles y un parque de patinaje; está prohibido nadar en sus estanques y en el río. Edgerton Park, en 75 Cliff Street, y West River Memorial Park, en 200 Derby Avenue, también figuran en el directorio municipal. Lighthouse Point Park, en 2 Lighthouse Road, tiene un faro histórico y un carrusel, pero la ciudad anuncia actualmente un cierre temporal por daños de tormenta: no planifiques entrar hasta que Parques confirme su reapertura. Antes de visitar cualquier parque, consulta horarios, cierres de senderos y permisos vigentes. Si estás pensando en mudarte, verifica las tasaciones e impuestos de cada propiedad con la ciudad, la inscripción escolar con el distrito y los servicios disponibles con los proveedores; la cercanía a un parque no garantiza derechos sobre una propiedad.",
    source:"https://www.newhavenct.gov/government/departments-divisions/parks-department/our-parks",
    places:["East Rock Park","Edgewood Park","Edgerton Park","West River Memorial Park","Lighthouse Point Park"]
  },

  westport:{
    en:"Westport's Sherwood Island State Park offers a mile of Long Island Sound shoreline, East and West beaches, salt-marsh walks, disc golf and a seasonal Nature Center. Sherwood Point holds Connecticut's Living 9/11 Memorial. The state lists daily park hours of 8 a.m. to sunset, but swimming conditions, parking fees and seasonal facilities should be checked before travel. The main pavilion is listed as closed for the 2026 season; the East Beach picnic shelter has a separate reservation season. Visitors should review posted beach and pet rules. Prospective residents can compare Westport neighborhoods while confirming each property's assessment and taxes, school assignment and utility availability directly with the town, district and service providers.",
    es:"Sherwood Island State Park, en Westport, ofrece aproximadamente una milla de costa junto a Long Island Sound, las playas East y West, paseos por marismas, disc golf y un centro de naturaleza de temporada. En Sherwood Point se encuentra el monumento conmemorativo viviente del 11 de septiembre de Connecticut. El estado indica un horario diario de 8:00 a. m. al atardecer, pero conviene verificar las condiciones de baño, tarifas de estacionamiento y servicios de temporada antes de viajar. El pabellón principal figura como cerrado durante la temporada 2026; el refugio para pícnic de East Beach tiene otro calendario de reservas. Consulta las normas de playa y mascotas. Si estás considerando mudarte, verifica las tasaciones e impuestos de cada vivienda, la asignación escolar y los servicios disponibles directamente con el municipio, el distrito y los proveedores.",
    source:"https://ctparks.com/node/132",
    places:["Sherwood Island State Park","East Beach","West Beach","Sherwood Island Nature Center","Connecticut Living 9/11 Memorial"]
  },

  "west-haven":{
    en:"The city describes a three-mile public shoreline beach corridor. West Haven\'s Long Island Sound shoreline includes Sandy Point Beach & Bird Sanctuary, a birdwatching destination with a Beach Street parking area and an observation deck. Sandy Point protects nesting and migrating shorebirds, so respect posted habitat closures and use nearby designated beaches for swimming instead. The city's shoreline recreation path links coastal stops including Morse Park and Bradley Point Park. Bradley Point also marks the July 1779 British landing; Savin Rock is another landmark in the city's waterfront history. Check the city for current beach parking permits, seasonal rules and water-quality advisories before visiting. If planning a move, verify each address's assessment, taxes, school enrollment and utility availability directly with the city, school district and providers.",
    es:"La ciudad describe un corredor público de playas de tres millas. La costa de West Haven junto a Long Island Sound incluye Sandy Point Beach & Bird Sanctuary, un lugar para observar aves con estacionamiento en Beach Street y una plataforma de observación. Sandy Point protege aves costeras migratorias y que anidan; respeta los cierres señalizados para proteger su hábitat y utiliza las playas designadas cercanas para nadar. Un paseo recreativo costero conecta lugares como Morse Park y Bradley Point Park. Bradley Point también recuerda el desembarco británico de julio de 1779; Savin Rock es otro punto de interés de la historia costera de la ciudad. Antes de visitar, consulta al municipio sobre permisos de estacionamiento, reglas de temporada y avisos de calidad del agua. Si piensas mudarte, verifica la tasación e impuestos de cada dirección, la inscripción escolar y la disponibilidad de servicios directamente con la ciudad, el distrito escolar y los proveedores.",
    source:"https://www.cityofwesthaven.com/294/Directions-to-Beaches",
    places:["Sandy Point Beach & Bird Sanctuary","Bradley Point Park","Morse Park","Savin Rock","West Haven Shoreline Recreation Path"]
  },

  stratford:{
    en:"Stratford sits along Long Island Sound and the Housatonic River, with shoreline recreation and inland open space. The town maintains Short Beach and Long Beach; beach access, parking stickers and nonresident charges are seasonal, so check current Recreation Department rules before visiting. Stratford Health Department samples beach water during the swimming season and may restrict swimming after heavy rainfall or elevated bacteria results. Boothe Memorial Park & Museum at 5800 Main Street has free, year-round park grounds, gardens and historic exhibits, with museum tours offered seasonally; confirm the tour schedule before traveling. Roosevelt Forest in northern Stratford offers a different, wooded outdoor setting, while Longbrook Park provides another local walking destination. For a move, check the property's current assessment and taxes with town offices, school enrollment and transportation with the district, and water, electricity, gas and internet availability with the providers for the exact address.",
    es:"Stratford se encuentra junto a Long Island Sound y el río Housatonic, con opciones recreativas en la costa y espacios naturales tierra adentro. El municipio mantiene Short Beach y Long Beach; el acceso, los permisos de estacionamiento y las tarifas para visitantes varían según la temporada, por lo que conviene consultar las normas vigentes del Departamento de Recreación. El Departamento de Salud analiza el agua de las playas durante la temporada de baño y puede restringir la natación después de lluvias intensas o resultados bacteriológicos elevados. Boothe Memorial Park & Museum, en 5800 Main Street, ofrece jardines, exposiciones históricas y terrenos gratuitos abiertos durante todo el año; las visitas al museo son de temporada y conviene confirmar el horario. Roosevelt Forest, en el norte de Stratford, ofrece un entorno boscoso diferente, mientras que Longbrook Park es otra opción para caminar. Antes de mudarte, confirma la tasación e impuestos de la propiedad con el municipio, la inscripción y el transporte escolar con el distrito, y la disponibilidad de agua, electricidad, gas e internet con los proveedores para la dirección exacta.",
    source:"https://www.stratfordct.gov/o/stratford/page/parks-department",
    places:["Short Beach","Long Beach","Boothe Memorial Park & Museum","Roosevelt Forest","Longbrook Park"]
  },

  norwalk:{
    en:"Norwalk's shoreline and park network offers a mix of beach outings, wooded walks and harbor views. Calf Pasture Beach and neighboring Shady Beach have shoreline paths and seasonal recreation facilities; check the city for swimming advisories and parking eligibility before going. Cranbury Park offers wooded trails and an 18-hole disc golf course, while Veterans Memorial Park and Marina has a harborfront walking esplanade, sports fields and boating facilities. Mathews Park connects cultural destinations with walking paths, and Oyster Shell Park offers another waterfront setting. Norwalk says seasonal parking charges generally apply May 15 through October 15 at several major parks; resident vehicle verification and nonresident restrictions vary by facility, so consult current city rules rather than assuming free access. If considering a move, verify assessment and tax records, school assignment and address-specific utility availability with the city, school district and providers.",
    es:"La red de parques y costa de Norwalk combina playas, senderos arbolados y vistas del puerto. Calf Pasture Beach y la cercana Shady Beach ofrecen paseos junto al agua e instalaciones recreativas de temporada; consulta los avisos sobre la calidad del agua y las condiciones de estacionamiento antes de ir. Cranbury Park tiene senderos entre árboles y un campo de disc golf de 18 hoyos, mientras que Veterans Memorial Park and Marina cuenta con un paseo frente al puerto, campos deportivos e instalaciones náuticas. Mathews Park conecta espacios culturales con senderos y Oyster Shell Park ofrece otro entorno costero. Según la ciudad, en varios parques importantes generalmente se cobran tarifas de estacionamiento del 15 de mayo al 15 de octubre; la verificación de vehículos de residentes y las restricciones para visitantes varían según el lugar. Consulta las normas municipales vigentes. Si piensas mudarte, verifica los registros de tasación e impuestos, la asignación escolar y los servicios disponibles para la dirección específica con la ciudad, el distrito escolar y los proveedores.",
    source:"https://www.norwalkct.gov/4021/Parks-Facilities",
    places:["Calf Pasture Beach","Shady Beach","Cranbury Park","Veterans Memorial Park and Marina","Mathews Park","Oyster Shell Park"]
  },
  northhaven:{
    en:"North Haven residents can explore Wharton Brook State Park, which spans the Wallingford–North Haven area along Route 5. The state describes wooded paths around a pond, fishing, picnic facilities and a designated swimming area. Swimming access depends on current water-quality advisories and seasonal conditions; check the Connecticut State Parks notices before entering the water. The park's picnic shelters require advance reservations for guaranteed use, and the state notes that those shelters are not wheelchair accessible. For a move to North Haven, confirm parcel assessments and taxes with the town, school enrollment and assignment with the district, and electricity, gas, water and internet service with providers for the exact address. Do not assume a nearby home's service or school assignment applies to another parcel.",
    es:"En el área de North Haven y Wallingford se encuentra Wharton Brook State Park, junto a la Ruta 5. Según el estado, este parque cuenta con senderos arbolados alrededor de un estanque, pesca, espacios para pícnic y una zona designada para nadar. Antes de entrar al agua, consulta los avisos vigentes sobre calidad del agua y las condiciones de temporada. Los refugios para pícnic pueden reservarse con anticipación y, según el estado, no son accesibles para usuarios de sillas de ruedas. Si estás considerando mudarte a North Haven, verifica la tasación y los impuestos de la parcela con el municipio, la inscripción y asignación escolar con el distrito, y los servicios de electricidad, gas, agua e internet con los proveedores para la dirección exacta. No supongas que los servicios o la escuela de una vivienda cercana corresponden a otra propiedad.",
    source:"https://ctparks.com/parks/wharton-brook-state-park",
    places:["Wharton Brook State Park"]
  },
  westhaven:{
    en:"West Haven's Long Island Sound shoreline includes Sandy Point Beach & Bird Sanctuary, a birdwatching destination where visitors should protect nesting and migrating shorebirds and avoid treating the sanctuary as a swimming beach. For swimming and shoreline recreation, explore the public beach areas near Bradley Point Park and Morse Park, subject to current conditions and posted restrictions. The beachfront walking route connects coastal destinations; Bradley Point also marks the site of the British landing on July 5, 1779. Beach parking rules and fees vary by residency and season, so consult the city's current notices rather than relying on older rates. Before moving, confirm the parcel's assessment and taxes with city offices, enrollment and school assignment with the district, and electricity, water, gas and internet availability directly with providers for the exact address.",
    es:"La costa de West Haven sobre Long Island Sound incluye Sandy Point Beach & Bird Sanctuary, un lugar para observar aves donde es importante proteger a las especies que anidan o descansan durante la migración; no se debe considerar el santuario una playa para nadar. Para nadar y disfrutar de la costa, consulta las zonas públicas cerca de Bradley Point Park y Morse Park, según las condiciones y restricciones vigentes. Un paseo costero conecta distintos lugares; Bradley Point también recuerda el desembarco británico del 5 de julio de 1779. Las normas y tarifas de estacionamiento en la playa pueden variar según la residencia y la temporada: revisa los avisos actuales de la ciudad en vez de confiar en precios antiguos. Antes de mudarte, confirma la tasación y los impuestos de la parcela con la ciudad, la inscripción y asignación escolar con el distrito y la disponibilidad de electricidad, agua, gas e internet con cada proveedor para la dirección exacta.",
    source:"https://www.cityofwesthaven.com/294/Directions-to-Beaches",
    places:["Sandy Point Beach & Bird Sanctuary","Bradley Point Park","Morse Park","West Haven Beachfront Walkway"]
  },
  "north-branford":{
    en:"North Branford includes both North Branford and Northford, with recreation facilities spread across the town. The municipal Parks and Recreation facility directory lists North Farms Park at 149 Branford Road, with a playground, hiking trail, soccer field and reservable covered pavilion. Northford Park at 1827 Middletown Avenue lists a playground, sports fields, basketball and tennis courts and a pavilion. Memorial Park at 654 Foxon Road has additional courts and ballfields; individual facilities can be temporarily closed, so check their current status before visiting. The Parks, Recreation and Senior Center office is at 1332 Middletown Avenue in Northford and provides program registration and facility requests. The town's Discover North Branford page also links to local hiking, historical resources and public schools. For a prospective move, confirm a parcel's assessment and taxes with town offices, enrollment and school assignments with the school district, and water, electricity, gas and internet availability with providers at the exact address. Do not assume a neighboring property has identical services.",
    es:"North Branford incluye las comunidades de North Branford y Northford, con instalaciones recreativas distribuidas por el municipio. El directorio municipal de Parques y Recreación incluye North Farms Park, en 149 Branford Road, con parque infantil, sendero, campo de fútbol y pabellón cubierto que se puede reservar. Northford Park, en 1827 Middletown Avenue, incluye juegos infantiles, campos deportivos, canchas de baloncesto y tenis y un pabellón. Memorial Park, en 654 Foxon Road, tiene otras canchas y campos; algunas instalaciones pueden cerrar temporalmente, por lo que conviene consultar su estado actual antes de ir. La oficina de Parques, Recreación y Centro para Personas Mayores está en 1332 Middletown Avenue, en Northford, y ofrece inscripciones a programas y solicitudes de reserva. La página municipal Discover North Branford también enlaza a senderos, recursos históricos y escuelas públicas. Antes de mudarte, confirma la tasación y los impuestos de la parcela con el municipio, la inscripción y asignación escolar con el distrito y la disponibilidad de agua, electricidad, gas e internet con cada proveedor para la dirección exacta. No supongas que las viviendas vecinas cuentan con los mismos servicios.",
    source:"https://northbranfordct.myrec.com/info/facilities/",
    places:["North Farms Park","Northford Park","Memorial Park at NBIS","Stanley T. Williams Community Center"]
  },
  trumbull:{
    en:"Trumbull offers varied recreation at Indian Ledge Park, Twin Brooks Park and Pequonnock River Valley Park. Indian Ledge Park at 307 Indian Ledge Park Road has sports fields, a BMX track, an amphitheater, a dog park, playgrounds and a seasonal water-spray area. Twin Brooks Park at 1 Twin Brooks Drive includes ponds, walking trails, a covered bridge and a memorial walkway. Pequonnock River Valley Park follows a scenic former railroad corridor, with a relatively level 2.5-mile rail-bed section and steeper trails on nearby ridges; the town lists limited parking off Tait Road and Whitney Avenue. The town says park stickers are required for parking at its municipal parks throughout the year, while its Pequonnock River Valley trail page says a sticker is not needed at the designated trail parking areas. Check the exact lot's current rules, facility conditions and event schedules before visiting. Prospective residents should verify each parcel's assessment, property-tax bill, school assignment, transportation and address-specific utility availability with town offices, the district and providers; park access does not establish property rights.",
    es:"Trumbull ofrece diversas opciones recreativas en Indian Ledge Park, Twin Brooks Park y Pequonnock River Valley Park. Indian Ledge Park, en 307 Indian Ledge Park Road, tiene campos deportivos, pista de BMX, anfiteatro, parque para perros, juegos infantiles y una zona de chorros de agua de temporada. Twin Brooks Park, en 1 Twin Brooks Drive, cuenta con estanques, senderos, un puente cubierto y un paseo conmemorativo. Pequonnock River Valley Park sigue un antiguo corredor ferroviario junto al río, con un tramo relativamente llano de unas 2,5 millas y senderos más empinados en las crestas cercanas; el municipio indica estacionamiento limitado cerca de Tait Road y Whitney Avenue. Según el municipio, se requieren distintivos para estacionar en sus parques durante todo el año, mientras que su página del sendero de Pequonnock River Valley indica que no hace falta distintivo en las zonas designadas para ese recorrido. Comprueba las normas de cada estacionamiento, las condiciones de las instalaciones y los eventos antes de ir. Si piensas mudarte, verifica la tasación y los impuestos de cada parcela, la asignación escolar, el transporte y la disponibilidad de servicios por dirección con el municipio, el distrito y los proveedores; el acceso a parques no establece derechos sobre una propiedad.",
    source:"https://www.trumbull-ct.gov/387/Parks-Facilities",
    places:["Indian Ledge Park","Twin Brooks Park","Pequonnock River Valley Park","Pequonnock River Trail","Robert G. Beach Memorial Park"]
  },
  monroe:{
    en:"Monroe offers varied recreation at Wolfe Park, 285 Cutlers Farm Road, with walking trails, athletic fields, tennis and pickleball facilities, and a seasonal outdoor pool. Great Hollow Lake, at 454 Purdy Hill Road, has a seasonal swimming area; the town reports that lake swimming and the Wolfe Park outdoor pool ended for the 2026 season on September 7, and lake bathrooms were winterized in October. Check current park passes, nonresident fees, swim advisories and facility status before visiting. Webb Mountain Park on Old Fish House Road has trails and reservable campsites; camping requires a town permit, and the published 2026 season ended November 7. The separate Webb Mountain Discovery Zone on Webb Circle offers educational nature trails and interpretive activities. For a move, confirm the parcel assessment and taxes with Monroe officials, enrollment and transportation with the school district, and electricity, water, heating and broadband service for the exact address with providers.",
    es:"Monroe ofrece diversas actividades recreativas en Wolfe Park, 285 Cutlers Farm Road, con senderos, campos deportivos, instalaciones de tenis y pickleball y una piscina exterior de temporada. Great Hollow Lake, en 454 Purdy Hill Road, tiene una zona de baño estacional; el municipio indica que la temporada de natación en el lago y la piscina exterior terminó el 7 de septiembre de 2026 y que los baños del lago se prepararon para el invierno en octubre. Consulta los pases, tarifas para no residentes, avisos sobre el agua y el estado de las instalaciones antes de ir. Webb Mountain Park, en Old Fish House Road, cuenta con senderos y campamentos reservables; para acampar se requiere permiso municipal y la temporada publicada de 2026 terminó el 7 de noviembre. Webb Mountain Discovery Zone, un espacio distinto en Webb Circle, ofrece senderos educativos y actividades interpretativas. Si piensas mudarte, confirma la tasación e impuestos de cada parcela con el municipio, la inscripción y el transporte con el distrito escolar y la disponibilidad de electricidad, agua, calefacción e internet en la dirección exacta con los proveedores.",
    source:"https://monroect.myrec.com/info/facilities/default.aspx",
    places:["Wolfe Park","Great Hollow Lake","Webb Mountain Park","Webb Mountain Discovery Zone"]
  },

  bridgeport:{
    en:"Bridgeport's waterfront and public parks offer different ways to explore the city. Seaside Park, designed in the nineteenth century by Frederick Law Olmsted and Calvert Vaux, stretches along Long Island Sound with beaches, lawns and athletic fields. Beardsley Park is another major city park, and its splash pad is listed at 1875 Noble Avenue. The city's 2026 parking rules provide free resident vehicle stickers for eligible Bridgeport registrations, while day-pass charges and checkpoints apply to other vehicles during the summer season; confirm current rates and access before visiting. Pleasure Beach is a separate coastal destination reached by seasonal water taxi: the city reports that its 2026 taxi season has ended, so do not assume the island is accessible by that service. Newfield Park and Washington Park also appear in the city's splash-pad directory. For anyone considering a move, compare neighborhoods using municipal maps and verify a particular property's assessment and taxes, public-school enrollment and address-specific utilities with the responsible agencies; nearby park access does not establish property entitlements.",
    es:"Los parques públicos y la costa de Bridgeport ofrecen distintas formas de conocer la ciudad. Seaside Park, diseñado en el siglo XIX por Frederick Law Olmsted y Calvert Vaux, se extiende junto a Long Island Sound con playas, jardines y campos deportivos. Beardsley Park es otro gran parque municipal; su zona de juegos de agua figura en 1875 Noble Avenue. Según las normas municipales de estacionamiento de 2026, los vehículos elegibles registrados en Bridgeport pueden obtener una calcomanía gratuita para residentes, mientras que durante el verano se aplican tarifas de pase diario y controles a otros vehículos; confirma los precios y el acceso vigentes antes de ir. Pleasure Beach es un destino costero distinto al que se llega mediante un taxi acuático de temporada: la ciudad informa que el servicio de 2026 ya terminó, así que no supongas que se puede acceder a la isla de esa manera. Newfield Park y Washington Park también figuran en el directorio municipal de zonas de juegos de agua. Si piensas mudarte, compara los barrios mediante mapas municipales y verifica la tasación e impuestos de cada propiedad, la inscripción escolar y los servicios disponibles en la dirección exacta con las entidades responsables; la cercanía a un parque no garantiza derechos de acceso especiales.",
    source:"https://www.bridgeportct.gov/government/departments/parks-recreation/park-sticker-information",
    places:["Seaside Park","Beardsley Park","Pleasure Beach","Newfield Park","Washington Park"]
  },

  newtown:{
    en:"Newtown offers town parks, woodland trails and water recreation across its neighborhoods, including Sandy Hook. Treadwell Memorial Park at 47 Philo Curtis Road has athletic fields, tennis courts, playgrounds and a seasonal swimming pool; pool admission and pavilion reservations have separate rules and fees. Dickinson Memorial Park at 50 Elm Drive includes courts, recreation areas and a skate park. Orchard Hill Nature Center on Huntingtown Road offers nature trails, while Fairfield Hills has a bicycle playground and community recreation spaces. Eichler's Cove provides access to Lake Zoar, with launch and beach use subject to current municipal permits. The town's posted park regulations list 8 a.m. to 8 p.m. hours for Treadwell, Dickinson and Orchard Hill; check for later updates and seasonal closures. Before moving, verify the exact property's assessment and taxes, school assignment, flood-map information and address-specific internet, electricity and other utilities with the town, district and providers. Park proximity does not imply unrestricted access or eligibility for a particular facility.",
    es:"Newtown ofrece parques municipales, senderos boscosos y actividades junto al agua en sus distintos barrios, incluido Sandy Hook. Treadwell Memorial Park, en 47 Philo Curtis Road, tiene campos deportivos, canchas de tenis, juegos infantiles y una piscina de temporada; la entrada a la piscina y las reservas de pabellones tienen normas y tarifas propias. Dickinson Memorial Park, en 50 Elm Drive, cuenta con canchas, espacios recreativos y un parque de patinaje. Orchard Hill Nature Center, en Huntingtown Road, ofrece senderos naturales, mientras que Fairfield Hills dispone de un espacio infantil para aprender a andar en bicicleta y otras áreas comunitarias. Eichler's Cove permite acceder a Lake Zoar, sujeto a los permisos municipales vigentes para embarcaciones y playa. Las normas publicadas por el municipio indican un horario de 8:00 a. m. a 8:00 p. m. para Treadwell, Dickinson y Orchard Hill; consulta posibles cambios y cierres de temporada. Antes de mudarte, verifica la tasación e impuestos de la propiedad exacta, la asignación escolar, los mapas de inundación y la disponibilidad de internet, electricidad y otros servicios con el municipio, distrito y proveedores. La cercanía a un parque no garantiza acceso sin restricciones ni el derecho a usar sus instalaciones.",
    source:"https://www.newtown-ct.gov/sites/g/files/vyhlif12216/f/pages/town_parks_rules_regulations_11.pdf",
    places:["Treadwell Memorial Park","Dickinson Memorial Park","Orchard Hill Nature Center","Fairfield Hills Bicycle Playground","Eichler's Cove"]
  },

};
